def longest_orfs(se,minlen=50):
    res=[]
    for frame in (0,1,2):
        s0=se[frame:]
        last_stop=-1
        for j in range(0,len(s0)-2,3):
            cod=s0[j:j+3]
            if code[cod]=='M' and j>last_stop:
                # find next stop
                k=j+3
                while k+2<len(s0) and code[s0[k:k+3]]!='*':
                    k+=3
                if k+2<len(s0):
                    length=(k-j)//3
                    if length>=minlen:
                        nt_start=frame+j
                        res.append((length,nt_start,nt_start+(k-j)+3, s0[j:k]))
                last_stop=k
            elif code[cod]=='*' :
                if j>last_stop:
                    last_stop=j
    return res

