def stopfree(sp):
    # sp: 0-based string; return list of (start1,end1,aaa) stop-free.
    res=[]
    for f in range(3):
        t=sp[f:]
        cur=None
        i=0
        while i+2<len(t)+2:
            c=stop=0
            if i+2<len(t):
                c=cod.get(t[i:i+3],'X'); stop=(c=='*')
            if not stop:
                if cur is None: cur=i
                i+=3
            else:
                if cur is not None:
                    res.append((f+cur, f+i-1))
                cur=None; i+=3
        if cur is not None:
            res.append((f+cur, f+(len(t)//3)*3))
    return res

